  update exercises set name = 'Seated Leg Curl Machine' where (owner_id is null or owner_id = uid) and name = 'Curl para isquiosurales sentado en máquina';
  update workout_sets ws set exercise_name = 'Seated Leg Curl Machine' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Curl para isquiosurales sentado en máquina';
  update exercises set name = 'Barbell Lunges (Quad-Focus)' where (owner_id is null or owner_id = uid) and name = 'Desplantes con barra (cuádriceps)';
