  update exercises set name = 'Eccentric Dragon Flag' where (owner_id is null or owner_id = uid) and name = 'Dragon flag excéntrica';
  update workout_sets ws set exercise_name = 'Eccentric Dragon Flag' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Dragon flag excéntrica';
  update exercises set name = 'Standing Alternating Dumbbell Front Raises' where (owner_id is null or owner_id = uid) and name = 'Elevaciones frontales de pie alternado con mancuernas';
  update workout_sets ws set exercise_name = 'Standing Alternating Dumbbell Front Raises' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevaciones frontales de pie alternado con mancuernas';
  update exercises set name = 'Single-Arm Incline Dumbbell Lateral Raise' where (owner_id is null or owner_id = uid) and name = 'Elevaciones laterales de lado a una mano con mancuerna en banco inclinado';
  update workout_sets ws set exercise_name = 'Single-Arm Incline Dumbbell Lateral Raise' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevaciones laterales de lado a una mano con mancuerna en banco inclinado';
  update exercises set name = 'Standing Dumbbell Lateral Raises' where (owner_id is null or owner_id = uid) and name = 'Elevaciones laterales de pie con mancuernas';
  update workout_sets ws set exercise_name = 'Standing Dumbbell Lateral Raises' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevaciones laterales de pie con mancuernas';
  update exercises set name = 'Hanging Knee Raises' where (owner_id is null or owner_id = uid) and name = 'Elevación de rodillas colgando';
  update workout_sets ws set exercise_name = 'Hanging Knee Raises' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevación de rodillas colgando';
  update exercises set name = 'Seated Calf Raise' where (owner_id is null or owner_id = uid) and name = 'Elevación de talones en costurera';
  update workout_sets ws set exercise_name = 'Seated Calf Raise' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevación de talones en costurera';
  update exercises set name = 'Calf Raise on 45° Leg Press (Lengthened Partials)' where (owner_id is null or owner_id = uid) and name = 'Elevación de talón en prensa a 45° parciales en elongación';
  update workout_sets ws set exercise_name = 'Calf Raise on 45° Leg Press (Lengthened Partials)' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevación de talón en prensa a 45° parciales en elongación';
  update exercises set name = 'Behind-the-Back Cable Lateral Raise (Mid-Height)' where (owner_id is null or owner_id = uid) and name = 'Elevación lateral con polea detrás del cuerpo (media altura)';
  update workout_sets ws set exercise_name = 'Behind-the-Back Cable Lateral Raise (Mid-Height)' from workouts w where ws.workout_id = w.id and w.user_id = uid and ws.exercise_name = 'Elevación lateral con polea detrás del cuerpo (media altura)';
